const _raw = $('POST /generate/orchestrated').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id    = $json.user_id;
// Capture bearer token for downstream RLS-scoped DB reads
const bearer_token = ($('POST /generate/orchestrated').item.json.headers?.authorization ||
                      $('POST /generate/orchestrated').item.json.headers?.Authorization || '')
                       .replace(/^Bearer\s+/i, '');
const upload_id  = (body.upload_id  || '').toString().trim();
const brief      = (body.brief      || '').toString().trim();
const session_id = body.session_id  ? body.session_id.toString() : null;
const room_type_raw = body.room_type   ? body.room_type.toString().trim() : null;
const UI_ROOM_TO_DB = { bedroom: 'bedroom', kids: 'kids room', dining: 'dining room', kitchen: 'kitchen', mandir: 'mandir', living: 'living room' };
const room_hint  = room_type_raw && UI_ROOM_TO_DB[room_type_raw] ? UI_ROOM_TO_DB[room_type_raw] : room_type_raw;
const style_tag  = body.style_tag   ? body.style_tag.toString().trim() : null;

const missing = [];
if (!upload_id) missing.push('upload_id');
if (!brief)     missing.push('brief');
if (missing.length) {
  return [{ json: { _error: { status: 400, body: { error: `missing_fields: ${missing.join(',')}`, code: 'invalid_request' } } } }];
}

const storage_path = `user-uploads/${user_id}/${upload_id}`;
const upload_url   = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${storage_path}`;
return [{ json: { user_id, bearer_token, upload_id, brief, session_id, room_hint, style_tag, upload_url, started_at_ms: Date.now() } }];

const ctx = $input.item.json;
const arrayBuf = await this.helpers.httpRequest({
  method: 'GET',
  url: ctx.upload_url,
  encoding: 'arraybuffer',
});
const b64 = Buffer.from(arrayBuf).toString('base64');
const mime = 'image/jpeg';
return [{ json: { ...ctx, upload_b64: b64, upload_mime: mime } }];

const ctx  = $input.item.json;
const b64  = ctx.upload_b64;
const mime = ctx.upload_mime || 'image/jpeg';
const dataUri = `data:${mime};base64,${b64}`;

const styleContext = ctx.style_tag
  ? `The user has selected style: "${ctx.style_tag}". Use this as the primary style direction.`
  : 'No style was pre-selected. Infer the best style from the user brief and room photo.';

const SYSTEM = `You are an interior-design reference retrieval and prompt-orchestration agent for Nano Banana 2.

Your mission: given a user\'s design brief, a style selection (if provided), and a photograph of the actual room, you must:
1. Interpret every usable specification in the brief.
2. Critically reason about the room\'s 3D spatial structure as visible in the photograph — wall positions visible, perceived depth, ceiling height, window placement and size, natural light direction, focal wall.
3. Write retrieval criteria that the NEXT AGENT will use to pick exactly 3 reference images from the database.
4. Write one curated Nano Banana 2 generation prompt.

${styleContext}

Output format — STRICT. No preamble. No code fences. Exactly two delimited blocks:

===CRITERIA===
Room type:
<state the room type explicitly>

3D spatial structure (grounded in photo):
<Precise observations: number of walls visible, room depth, ceiling height (low/standard/high/vaulted), window wall position (left/right/back/front/multiple), natural light direction and intensity, floor coverage visible>

Style intent:
<Target aesthetic, material palette, colour story — use selected style if provided>

Daylight & ambience:
<Lighting mood, warmth, time-of-day feel desired in the output>

Functional requirements:
<Furniture types, zones, layout priorities>

Complementarity guidance:
Reference 1 must match the 3D spatial geometry: similar room proportions, ceiling height, and window placement.
Reference 2 must match the style, materials, and colour palette.
Reference 3 must match the lighting quality and ambience.
===END===

===PROMPT===
<One polished Nano Banana 2 creative brief in natural sentences. Must: (a) instruct to preserve the exact room geometry shown in the first input image — walls, windows, ceiling; (b) apply style \'${ctx.style_tag || 'as derived from brief'}\'; (c) describe the desired furnishing, materials, palette, and lighting. No keyword soup. No people, no text, no logos.>
===END===`;

const openrouter_body = {
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: [
      { type: 'text', text: `User brief:\n${ctx.brief}\n\n${ctx.style_tag ? `Selected style: ${ctx.style_tag}\n\n` : ''}Room type hint: ${ctx.room_hint || '(infer from photo)'}\n\nRoom photograph attached. Ground ALL 3D spatial reasoning in this image — do not assume, only observe.` },
      { type: 'image_url', image_url: { url: dataUri } }
    ]}
  ],
  temperature: 0.4,
  max_tokens: 2048
};

return [{ json: { ...ctx, openrouter_body } }];

const ctx     = $('Build Agent 1 request').item.json;
const resp    = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
if (!content) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_empty_response', code: 'upstream_error' } } } }];
}

function extractBlock(text, startTag) {
  const startRe = new RegExp(`={3,}\\s*${startTag}\\s*={3,}`, 'i');
  const endRe   = /={3,}\s*END\s*={3,}/i;
  const s = text.search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  if (e < 0) return after.trim();
  return after.slice(0, e).trim();
}

const criteria = extractBlock(content, 'CRITERIA');
const prompt   = extractBlock(content, 'PROMPT');
if (!criteria || !prompt) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_bad_format', code: 'upstream_error', raw: content.slice(0, 500) } } } }];
}

const roomWordsRaw = ['bedroom','living room','kitchen','dining room','bathroom','office','study room','kids room','nursery','hallway','entryway','mandir'];
const roomWords = [...roomWordsRaw].sort((a, b) => b.length - a.length);
const lc = (criteria + ' ' + (ctx.brief || '') + ' ' + (ctx.room_hint || '')).toLowerCase();
let inferred_room = ctx.room_hint || null;
if (!inferred_room) {
  for (const w of roomWords) { if (lc.includes(w)) { inferred_room = w; break; } }
}

const ftsTerms = [ctx.brief, ctx.style_tag, inferred_room].filter(Boolean).join(' ');

return [{ json: { ...ctx, criteria, agent_prompt: prompt, inferred_room, fts_search_text: ftsTerms } }];

let rows;
if (Array.isArray($json)) {
  rows = $json;
} else if (Array.isArray($json?.body)) {
  rows = $json.body;
} else if ($json?.body && typeof $json.body === 'object') {
  rows = [$json.body];
} else if ($json && typeof $json === 'object') {
  rows = [$json];
} else {
  rows = [];
}
function dedupePool(arr) {
  const seen = new Set();
  const seenUrl = new Set();
  const out = [];
  for (const r of arr) {
    if (!r || r.id == null) continue;
    const id = r.id.toString().toLowerCase();
    const u = (r.source_url || '').split('?')[0].trim().toLowerCase();
    if (seen.has(id)) continue;
    if (u && seenUrl.has(u)) continue;
    seen.add(id);
    if (u) seenUrl.add(u);
    out.push(r);
  }
  return out;
}
const pool = dedupePool(rows);
const ctx  = $('Parse Agent 1').item.json;
const pool_empty    = pool.length === 0;
const pool_fallback = pool.length > 0 && pool.length < 3;
return [{ json: { ...ctx, pool, pool_empty, pool_fallback } }];

parameters.url:
={{ (() => {
  const c = $json;
  const base = 'https://uzghfpxboktnbcbbthns.supabase.co/rest/v1/reference_images?select=id,source_url,caption,room_type,style_tags,dominant_colors,detected_objects,quality_score&owner_id=eq.' + encodeURIComponent(c.user_id) + '&order=quality_score.desc.nullslast&limit=20';
  const st = (c.style_tag || '').toString().trim();
  const rm = (c.inferred_room || c.room_hint || '').toString().trim();
  const styleTop = st ? ('&style_tags=cs.%7B' + encodeURIComponent(st) + '%7D') : '';
  const roomTop  = rm ? ('&room_type=eq.' + encodeURIComponent(rm)) : '';
  return base + roomTop + styleTop;
})() }}

