let rows;
if (Array.isArray($json)) {
  rows = $json;
} else if (Array.isArray($json?.body)) {
  rows = $json.body;
} else if ($json?.body && typeof $json.body === 'object') {
  rows = [$json.body];
} else if ($json && typeof $json === 'object') {
  rows = [$json];
} else {
  rows = [];
}
function dedupePool(arr) {
  const seen = new Set();
  const seenUrl = new Set();
  const out = [];
  for (const r of arr) {
    if (!r || r.id == null) continue;
    const id = r.id.toString().toLowerCase();
    const u = (r.source_url || '').split('?')[0].trim().toLowerCase();
    if (seen.has(id)) continue;
    if (u && seenUrl.has(u)) continue;
    seen.add(id);
    if (u) seenUrl.add(u);
    out.push(r);
  }
  return out;
}
const fb = dedupePool(rows);
const ctx  = $('Check pool').item.json;
const primary = dedupePool(Array.isArray(ctx.pool) ? ctx.pool : []);
const merged = dedupePool([...primary, ...fb]);
const pool = merged.slice(0, 20);
return [{ json: { ...ctx, pool, pool_fallback: false } }];

const ctx  = $json;
function dedupePool(arr) {
  const seen = new Set();
  const seenUrl = new Set();
  const out = [];
  for (const r of arr) {
    if (!r || r.id == null) continue;
    const id = r.id.toString().toLowerCase();
    const u = (r.source_url || '').split('?')[0].trim().toLowerCase();
    if (seen.has(id)) continue;
    if (u && seenUrl.has(u)) continue;
    seen.add(id);
    if (u) seenUrl.add(u);
    out.push(r);
  }
  return out;
}
const pool = dedupePool(ctx.pool || []);
if (pool.length === 0) {
  return [{ json: { _error: { status: 500, body: { error: 'pool_empty', code: 'internal_error', count: 0 } } } }];
}
if (pool.length < 3) {
  return [{ json: { _error: { status: 422, body: { error: 'insufficient_distinct_pool', code: 'pool_too_small', distinct: pool.length } } } }];
}

const SYSTEM = `You are a spatial-aware reference-image selector for an interior design AI pipeline.

You receive:
1. A CRITERIA block from a design director, including 3D spatial structure observations of the user's room.
2. A pool of candidate reference images, each shown as a card.

Card format:
[id=<uuid>] <enhanced caption or fallback caption>
  spatial: shape=<room_shape> depth=<depth_cues> ceil=<ceiling_height> win=<window_wall> light=<light_direction> sym=<symmetry>
  style:[<tags>] colors:[<hex>] room:<room_type>

Your task: Pick exactly 3 reference IDs whose COMBINED coverage best satisfies the criteria.

PICKING RULES (in priority order):
Reference 1 — SPATIAL MATCH: must have the closest 3D geometry to the user\'s room.
  Look for: same ceiling_height, same window_wall position, similar depth_cues, similar room_shape.
Reference 2 — STYLE MATCH: must best represent the target style, materials, and colour palette.
Reference 3 — AMBIENCE MATCH: must best represent the target lighting quality and mood.

Constraints: complementary picks only (not redundant). Never invent IDs. Never repeat IDs.

Output — STRICT. Exactly three lines, nothing else:
Reference 1: <uuid> — <one sentence: which spatial feature matched>
Reference 2: <uuid> — <one sentence: which style/material matched>
Reference 3: <uuid> — <one sentence: which lighting/ambience matched>`;

const cards = pool.map(r => {
  const style   = Array.isArray(r.style_tags) ? r.style_tags.join(',') : '';
  const colors  = Array.isArray(r.dominant_colors) ? r.dominant_colors.join(',') : '';
  const cap     = (r.caption_enhanced || r.caption || '').replace(/\s+/g, ' ').trim().slice(0, 200);

  let spatialLine = '';
  const s = r.spatial_sig || r.spatial_signature;
  if (s && typeof s === 'object') {
    spatialLine = `\n  spatial: shape=${s.room_shape||'?'} depth=${s.depth_cues||'?'} ceil=${s.ceiling_height||'?'} win=${s.window_wall||'?'} light=${s.light_direction||'?'} sym=${s.symmetry||'?'}`;
  }

  return `[id=${r.id}] ${cap}${spatialLine}\n  style:[${style}] colors:[${colors}] room:${r.room_type||'?'}`;
}).join('\n\n');

const user = `===CRITERIA===\n${ctx.criteria}\n===END===\n\n===CANDIDATES===\n${cards}\n===END===`;

const openrouter_body = {
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user',   content: user }
  ],
  temperature: 0.2,
  max_tokens: 512
};

return [{ json: { ...ctx, pool, openrouter_body } }];

const ctx  = $('Build Agent 2 request').item.json;
const resp = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
const uuidRe = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
const matches = (content.match(uuidRe) || []).map(s => s.toLowerCase());

const poolRows = ctx.pool || [];
const poolIds = new Set(poolRows.map(r => r.id.toString().toLowerCase()));
const seen = new Set();
const picks = [];

for (const m of matches) {
  if (!poolIds.has(m)) continue;
  if (seen.has(m)) continue;
  seen.add(m);
  picks.push(m);
  if (picks.length === 3) break;
}

if (picks.length < 3) {
  const sorted = [...poolRows].sort((a, b) => (b.quality_score || 0) - (a.quality_score || 0));
  for (const r of sorted) {
    const id = r.id.toString().toLowerCase();
    if (seen.has(id)) continue;
    seen.add(id);
    picks.push(id);
    if (picks.length === 3) break;
  }
}

if (picks.length < 3) {
  return [{ json: { _error: { status: 422, body: { error: 'insufficient_distinct_picks', code: 'retriever_short', pick_count: picks.length, pool_distinct: poolRows.length } } } }];
}

return [{ json: { ...ctx, picked_reference_ids: picks } }];

const ctx  = $('Parse Agent 2').item.json;
let refs;
if (Array.isArray($json)) {
  refs = $json;
} else if (Array.isArray($json?.body)) {
  refs = $json.body;
} else if ($json?.body && typeof $json.body === 'object' && $json.body.id != null) {
  refs = [$json.body];
} else if ($json && typeof $json === 'object' && $json.id != null) {
  refs = [$json];
} else {
  refs = [];
}
const byId = {};
refs.forEach(r => { byId[r.id.toString().toLowerCase()] = r.source_url; });

const pickIds = [];
const seenId = new Set();
for (const raw of ctx.picked_reference_ids || []) {
  const id = raw.toString().toLowerCase();
  if (seenId.has(id)) continue;
  seenId.add(id);
  pickIds.push(id);
}
if (pickIds.length !== 3) {
  return [{ json: { _error: { status: 422, body: { error: 'picked_ids_not_three_unique', code: 'internal_error', distinct_pick_count: pickIds.length } } } }];
}
const refUrls = pickIds.map(id => byId[id]).filter(Boolean);
if (refUrls.length !== 3) {
  return [{ json: { _error: { status: 500, body: { error: 'picked_reference_url_missing', code: 'internal_error' } } } }];
}
const norm = (u) => (u || '').split('?')[0].trim().toLowerCase();
const seenUrl = new Set();
for (const u of refUrls) {
  const n = norm(u);
  if (seenUrl.has(n)) {
    return [{ json: { _error: { status: 422, body: { error: 'duplicate_reference_source_url', code: 'internal_error' } } } }];
  }
  seenUrl.add(n);
}
const urls = [ctx.upload_url, ...refUrls];
return urls.map((url, i) => ({ json: { ...ctx, picked_reference_ids: pickIds, idx: i, fetch_url: url } }));

const items = $input.all();
items.sort((a, b) => a.json.idx - b.json.idx);
const parts = items.map(it => {
  const bin = it.binary.image;
  return {
    type: 'image_url',
    image_url: { url: `data:${bin.mimeType || 'image/png'};base64,${bin.data}` }
  };
});
return [{ json: { ...items[0].json, image_parts: parts } }];

let rows;
if (Array.isArray($json)) {
  rows = $json;
} else if (Array.isArray($json?.body)) {
  rows = $json.body;
} else if ($json?.body && typeof $json.body === 'object') {
  rows = [$json.body];
} else if ($json && typeof $json === 'object' && ($json.value != null || $json.key != null)) {
  rows = [$json];
} else {
  rows = [];
}
const model = (rows[0] && rows[0].value) || 'google/gemini-3.1-flash-image-preview';
const ctx   = $('Collect image parts').item.json;

const openrouter_body = {
  model,
  messages: [{
    role: 'user',
    content: [{ type: 'text', text: ctx.agent_prompt }, ...(ctx.image_parts || [])]
  }]
};

return [{ json: { ...ctx, model, openrouter_body } }];

const ctx  = $('Build Gemini request').item.json;
const resp = $json;
// OpenRouter returns choices[0].message.content as array of content parts
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || [];
const parts   = Array.isArray(content) ? content : [];
const imgPart = parts.find(p => p.type === 'image_url');
if (!imgPart) {
  return [{ json: { _error: { status: 502, body: { error: 'no_image_in_response', code: 'upstream_error' } } } }];
}
const dataUrl = imgPart.image_url && imgPart.image_url.url;
const match   = dataUrl && dataUrl.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  return [{ json: { _error: { status: 502, body: { error: 'invalid_image_data_url', code: 'upstream_error' } } } }];
}
const mime = match[1];
const b64  = match[2];
const latency_ms = Date.now() - ctx.started_at_ms;

return [{
  json: {
    user_id:              ctx.user_id,
    session_id:           ctx.session_id,
    parent_generation_id: null,
    kind:                 'orchestrated',
    input_image_path:     `user-uploads/${ctx.user_id}/${ctx.upload_id}`,
    room_type:            ctx.inferred_room || null,
    style_tag:            ctx.style_tag || null,
    reference_image_ids:  ctx.picked_reference_ids,
    prompt:               ctx.agent_prompt,
    criteria:             ctx.criteria,
    model_config:         'A',
    model_id:             ctx.model,
    latency_ms,
    cost_usd:             0
  },
  binary: { output_png: { data: b64, mimeType: mime, fileExtension: 'png', fileName: 'output.png' } }
}];

